example.script:
import { signal } from "rewind";
export default async function main(input: { repo: string }) {
  const { close } = await signal("approval");
  return { closed: close ? 1 : 0 };
}

displayName.description:
The customer's label for the end user (`Acme Corp`), shown beside the name, which stays
its key everywhere. Trimmed; at most 128 characters, none of them a control character;
not unique. `null` or `""` removes it.

example.script:
import { github } from "rewind:tools";
export default async function main(input: { repo: string }) {
  return (await github.list_issues({ repo: input.repo })).length;
}

import { github } from "rewind:tools";
export default async function main(input: { repo: string }) {
  const issues = await github.list_issues({ repo: input.repo, state: "open" });
  return { open: issues.length };
}

post.description:
A valid access token, refreshed when less than a minute is left; with `organizationId`,
for that organization. A member's first session in an organization writes their grant:
the pending grant of the invitation they accepted, else the organization's default role.
